import{_ as s,o as n,c as l,ah as r}from"./chunks/framework.CfQBrslM.js";const c="/projects/AiArm/en/latest/assets/image2.DrZOta1R.png",d="/projects/AiArm/en/latest/assets/image2.BhJdMx_u.png",g="/projects/AiArm/en/latest/assets/image3.DJGbNCpu.png",e="data:image/png;base64,",m="/projects/AiArm/en/latest/assets/image5.Cg7qPwS8.png",h="data:image/png;base64,",A="/projects/AiArm/en/latest/assets/image7.Df1x2KeX.png",p="/projects/AiArm/en/latest/assets/image8.BV8Ceh7b.png",u="/projects/AiArm/en/latest/assets/image10.CIYxHdv9.png",w="/projects/AiArm/en/latest/assets/image11.B3yea5DZ.png",y="/projects/AiArm/en/latest/assets/image12.DpIlI7iF.png",f="/projects/AiArm/en/latest/assets/image13.YHlsYZCo.png",b="data:image/png;base64,",x="/projects/AiArm/en/latest/assets/image15.Gb9EflCV.png",C="data:image/png;base64,",M="/projects/AiArm/en/latest/assets/image15.DtOOevuT.png",k="/projects/AiArm/en/latest/assets/image2.BHi-q0Rb.png",q="/projects/AiArm/en/latest/assets/image3.B-MwVcsR.png",V="/projects/AiArm/en/latest/assets/image2.BhJdMx_u.png",O="/projects/AiArm/en/latest/assets/image3.DJGbNCpu.png",o="data:image/png;base64,",B="/projects/AiArm/en/latest/assets/image5.Cg7qPwS8.png",W="data:image/png;base64,",v="/projects/AiArm/en/latest/assets/image7.Df1x2KeX.png",I="/projects/AiArm/en/latest/assets/image8.BV8Ceh7b.png",T="/projects/AiArm/en/latest/assets/image11.2w4oh98k.png",S="/projects/AiArm/en/latest/assets/image12.B_ol3h2e.png",N="/projects/AiArm/en/latest/assets/image13.wQquuVeV.png",P="data:image/png;base64,",z="/projects/AiArm/en/latest/assets/image15.Gb9EflCV.png",G="data:image/png;base64,",Q="/projects/AiArm/en/latest/assets/image15.DtOOevuT.png",D="/projects/AiArm/en/latest/assets/image2.DObE7EEJ.png",L="/projects/AiArm/en/latest/assets/image3.DbEI4ZE8.png",K="/projects/AiArm/en/latest/assets/image4.xYpzNccs.png",R="/projects/AiArm/en/latest/assets/image2.BhJdMx_u.png",F="/projects/AiArm/en/latest/assets/image3.DJGbNCpu.png",a="data:image/png;base64,",H="/projects/AiArm/en/latest/assets/image5.Cg7qPwS8.png",X="data:image/png;base64,",Y="/projects/AiArm/en/latest/assets/image7.Df1x2KeX.png",U="/projects/AiArm/en/latest/assets/image8.BV8Ceh7b.png",E="/projects/AiArm/en/latest/assets/image12.BgAmOHaZ.png",J="/projects/AiArm/en/latest/assets/image13.DfdLzlHN.png",Z="/projects/AiArm/en/latest/assets/image14.CPHl0aIB.png",j="/projects/AiArm/en/latest/assets/image15.B57fadAs.png",_="data:image/png;base64,",$="/projects/AiArm/en/latest/assets/image15.Gb9EflCV.png",tt="data:image/png;base64,",et="/projects/AiArm/en/latest/assets/image15.DtOOevuT.png",ot="/projects/AiArm/en/latest/assets/image2.Dl_wi3M9.png",at="/projects/AiArm/en/latest/assets/image2.BhJdMx_u.png",it="/projects/AiArm/en/latest/assets/image3.DJGbNCpu.png",i="data:image/png;base64,",st="/projects/AiArm/en/latest/assets/image5.Cg7qPwS8.png",nt="data:image/png;base64,",lt="/projects/AiArm/en/latest/assets/image7.Df1x2KeX.png",rt="/projects/AiArm/en/latest/assets/image8.BV8Ceh7b.png",ct="/projects/AiArm/en/latest/assets/image10.C9qaD_bW.png",dt="/projects/AiArm/en/latest/assets/image11.BGpgaumW.png",gt="/projects/AiArm/en/latest/assets/image12.7vxKFyGD.png",mt="/projects/AiArm/en/latest/assets/image13.Btd8jhWc.png",ht="data:image/png;base64,",At="/projects/AiArm/en/latest/assets/image15.Gb9EflCV.png",pt="data:image/png;base64,",ut="/projects/AiArm/en/latest/assets/image15.DtOOevuT.png",qt=JSON.parse('{"title":"4. Sensor Application","description":"","frontmatter":{},"headers":[],"relativePath":"docs/4.Sensor Application.md","filePath":"docs/4.Sensor Application.md"}'),wt={name:"docs/4.Sensor Application.md"};function yt(ft,t,bt,xt,Ct,Mt){return n(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="_4-sensor-application" tabindex="-1">4. Sensor Application <a class="header-anchor" href="#_4-sensor-application" aria-label="Permalink to &quot;4. Sensor Application&quot;">​</a></h1><h2 id="_4-1-intelligent-fan" tabindex="-1">4.1 Intelligent Fan <a class="header-anchor" href="#_4-1-intelligent-fan" aria-label="Permalink to &quot;4.1 Intelligent Fan&quot;">​</a></h2><h3 id="_4-1-1-introduction" tabindex="-1">4.1.1 Introduction <a class="header-anchor" href="#_4-1-1-introduction" aria-label="Permalink to &quot;4.1.1 Introduction&quot;">​</a></h3><ol><li>This module is designed to enable motor rotation without the need for an additional motor driver board. It offers the flexibility to adjust the speed and direction of rotation as desired. Furthermore, it can be seamlessly integrated with various sensors, allowing for the creation of intelligent fan project.</li></ol><img loading="lazy" height="360" width="609" src="'+c+'" class="common_img" style="width:500px;"><h3 id="_4-1-2-working-logic" tabindex="-1">4.1.2 Working Logic <a class="header-anchor" href="#_4-1-2-working-logic" aria-label="Permalink to &quot;4.1.2 Working Logic&quot;">​</a></h3><ol><li>Utilizing IIC communication, the fan module effectively converts a preset digital signal into an analog signal using a Digital-to-Analog Converter (DAC).</li><li>This analog signal is then transmitted to the fan module, enabling seamless adjustment of the fan&#39;s speed and rotation direction.</li></ol><h3 id="_4-1-3-module-features" tabindex="-1">4.1.3 Module Features <a class="header-anchor" href="#_4-1-3-module-features" aria-label="Permalink to &quot;4.1.3 Module Features&quot;">​</a></h3><ol><li><p>Adjustable fan’s speed and rotation direction.</p></li><li><p>The module reserves holes for DIY expansion.</p></li></ol><h3 id="_4-1-4-module-parameters" tabindex="-1">4.1.4 Module Parameters <a class="header-anchor" href="#_4-1-4-module-parameters" aria-label="Permalink to &quot;4.1.4 Module Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Working voltage voltage</th><th style="text-align:center;">Communication</th><th style="text-align:center;">Working current</th><th style="text-align:center;">Size</th></tr></thead><tbody><tr><td style="text-align:center;">5V</td><td style="text-align:center;">IIC</td><td style="text-align:center;">125mA</td><td style="text-align:center;">48mm*48mm</td></tr></tbody></table><h3 id="_4-1-5-preparation" tabindex="-1">4.1.5 Preparation <a class="header-anchor" href="#_4-1-5-preparation" aria-label="Permalink to &quot;4.1.5 Preparation&quot;">​</a></h3><ol><li><p>Install the fan module to the corresponding position according to the tutorial in “<strong>1. Getting Ready Lesson 2 Props and Map</strong>”, and connect it to port 3 of CoreX controller.</p></li><li><p>Install WonderCode software referring to the instructions provided in “<strong>3. Scratch Programming\\Lesson 1 WonderCode Installation</strong>”.</p></li></ol><h3 id="_4-1-6-program-logic" tabindex="-1">4.1.6 Program Logic <a class="header-anchor" href="#_4-1-6-program-logic" aria-label="Permalink to &quot;4.1.6 Program Logic&quot;">​</a></h3><ol><li>Upon AiArm starts, it will initialize port 3 where fan module is connected. Then it will employ loop statement to enable the fan module to rotate in this cycle “<strong>rotate forward -&gt; stop -&gt; rotate reversely -&gt; stop</strong>”.</li><li>Please set the speed in sequence as below in the main program.</li></ol><p>​ (1) <strong>Rotate forward</strong>: Set the speed to 60 and duration to 3 seconds</p><p>​ (2) <strong>Stop</strong>: set the speed to 0 and the duration to 1.2 second.</p><p>​ (3) <strong>Rotate reversely</strong>: set the speed to -60 and the duration to 3 seconds</p><p>​ (4) <strong>Stop</strong>: set the speed to 0 and the duration to 1.2 seconds</p><ol start="3"><li>Repeat the above steps to enable the fan module to realize “<strong>rotate forward -&gt; stop -&gt; rotate reversely</strong>”.</li></ol><h3 id="_4-1-7-connection" tabindex="-1">4.1.7 Connection <a class="header-anchor" href="#_4-1-7-connection" aria-label="Permalink to &quot;4.1.7 Connection&quot;">​</a></h3><ol><li>Connect the CoreX controller and computer using USB cable, then turn on the controller.</li></ol><img loading="lazy" height="427" width="918" src="'+d+'" class="common_img" style="width:800px;"><ol start="2"><li>Open “<strong>WonderCode</strong>” software.</li></ol><img loading="lazy" height="101" width="72" src="'+g+'" class="common_img" style="width:200px;"><ol start="3"><li>Click on the <img loading="lazy" height="65" width="75" src="'+e+'" class="inline-icon"> located at the lower left corner and select <strong>AiArm</strong> from the available options. This software will automatically establish a connection with AiArm in the subsequent operations.</li></ol><img loading="lazy" height="861" width="1384" src="'+m+'" class="common_img" style="width:800px;"><ol start="4"><li>Click-on <img loading="lazy" height="48" width="154" src="'+h+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p><img loading="lazy" height="108" width="525" src="'+A+'" class="common_img" style="width:500px;"></div><ol start="5"><li>Once the connection is established successfully, the below prompt will appear.</li></ol><img loading="lazy" height="162" width="606" src="'+p+'" class="common_img" style="width:800px;"><h3 id="_4-1-8-write-programs" tabindex="-1">4.1.8 Write Programs <a class="header-anchor" href="#_4-1-8-write-programs" aria-label="Permalink to &quot;4.1.8 Write Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="65" width="75" src="'+e+'" class="inline-icon"> at the lower left corner. Then enter <strong>“Output Module”</strong> section and select Fan.</li></ol><img loading="lazy" height="445" width="1083" src="'+u+'" class="common_img" style="width:800px;"><ol start="2"><li>When powering on AiArm, ensure that the port is set to 3, while leaving the address at its default value.</li></ol><img loading="lazy" height="110" width="455" src="'+w+'" class="common_img" style="width:500px;"><ol start="3"><li><p>Incorporate the following code blocks into the main program in sequence:</p><p>(1) <strong>Block 1</strong>: Set the speed to 60 and the duration to 3 seconds.</p><p>(2) <strong>Block 2</strong>: Set the speed to 0 and the duration to 1.2 seconds.</p><p>(3) <strong>Block 3</strong>: Set the speed to -60 and the duration to 3 seconds.</p><p>(4) <strong>Block 4</strong>: Set the speed to 0 and the duration to 1.2 seconds.</p></li></ol><img loading="lazy" height="411" width="598" src="'+y+'" class="common_img" style="width:500px;"><ol start="4"><li>The complete code block is as below.</li></ol><img loading="lazy" height="550" width="948" src="'+f+'" class="common_img" style="width:800px;"><h3 id="_4-1-9-download-programs" tabindex="-1">4.1.9 Download Programs <a class="header-anchor" href="#_4-1-9-download-programs" aria-label="Permalink to &quot;4.1.9 Download Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="45" width="46" src="'+b+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="119" width="442" src="'+x+'" class="common_img" style="width:800px;"><ol start="2"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+C+'" class="common_img" style="width:300px;"><h3 id="_4-1-10-save-programs" tabindex="-1">4.1.10 Save Programs <a class="header-anchor" href="#_4-1-10-save-programs" aria-label="Permalink to &quot;4.1.10 Save Programs&quot;">​</a></h3><ol><li>Click-on <strong>File -&gt; Save to your computer.</strong></li></ol><img loading="lazy" height="175" width="513" src="'+M+'" class="common_img" style="width:800px;"><h3 id="_4-1-11-program-outcome" tabindex="-1">4.1.11 Program Outcome <a class="header-anchor" href="#_4-1-11-program-outcome" aria-label="Permalink to &quot;4.1.11 Program Outcome&quot;">​</a></h3><ol><li>Once the program is downloaded successfully, power on AiArm.</li><li>Then the fan module will rotate forward for 3 seconds, then stop for 1.2 second, next rotate reversely for 3 seconds, lastly stop for 1.2 second.</li></ol><h2 id="_4-2-dot-matrix-display" tabindex="-1">4.2 Dot Matrix Display <a class="header-anchor" href="#_4-2-dot-matrix-display" aria-label="Permalink to &quot;4.2 Dot Matrix Display&quot;">​</a></h2><ol><li>Once the program is downloaded successfully, power on the robot arm and turn on CoreX controller. The dot matrix display will demonstrate number “<strong>123</strong>” for 1 second, then automatically shut down.</li></ol><h3 id="_4-2-1-introduction" tabindex="-1">4.2.1 Introduction <a class="header-anchor" href="#_4-2-1-introduction" aria-label="Permalink to &quot;4.2.1 Introduction&quot;">​</a></h3><ol><li>The dot matrix display comprises an 8x16 point board. Through programming, we can command the dot matrix display to display the desired pattern.</li></ol><img loading="lazy" height="354" width="775" src="'+k+'" class="common_img" style="width:400px;"><h3 id="_4-2-2-working-logic" tabindex="-1">4.2.2 Working Logic <a class="header-anchor" href="#_4-2-2-working-logic" aria-label="Permalink to &quot;4.2.2 Working Logic&quot;">​</a></h3><ol><li><p>The dot matrix module is comprised of diodes (LEDs). It operates by utilizing X and Y coordinates to specify LED to display. The X coordinate represents the horizontal position, while the Y coordinate represents the vertical position.</p></li><li><p>The level can be understood as the strength of the voltage signal. When a specific column is set to a level of 1, the corresponding LED will light up, and when a certain row is set to a level of 0, the corresponding LED will be turned off.</p></li><li><p>The figure below illustrates the corresponding coordinate positions within the 8x16 dot matrix grid.</p></li></ol><img loading="lazy" height="399" width="786" src="'+q+'" class="common_img" style="width:400px;"><ol start="4"><li>In the 8x16 dot matrix grid, the coordinate of the lower left corner is denoted as (0, 0), with X = 0 and Y = 0. When moving one grid to the right, the X coordinate increases by 1 in a sequential manner. Similarly, when moving one grid upwards, the Y coordinate increases by 1 in a sequential manner.</li></ol><h3 id="_4-2-3-module-features" tabindex="-1">4.2.3 Module Features <a class="header-anchor" href="#_4-2-3-module-features" aria-label="Permalink to &quot;4.2.3 Module Features&quot;">​</a></h3><ol><li>High brightness, no flicker and easy wiring.</li></ol><h3 id="_4-2-4-module-parameters" tabindex="-1">4.2.4 Module Parameters <a class="header-anchor" href="#_4-2-4-module-parameters" aria-label="Permalink to &quot;4.2.4 Module Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Working voltage voltage</th><th style="text-align:center;">Communication</th><th style="text-align:center;">Working current</th><th style="text-align:center;">Size</th></tr></thead><tbody><tr><td style="text-align:center;">5V</td><td style="text-align:center;">I/O</td><td style="text-align:center;">45mA</td><td style="text-align:center;">56mm*24mm</td></tr></tbody></table><h3 id="_4-2-5-preparation" tabindex="-1">4.2.5 Preparation <a class="header-anchor" href="#_4-2-5-preparation" aria-label="Permalink to &quot;4.2.5 Preparation&quot;">​</a></h3><ol><li><p>Install the dot matrix display to the corresponding position according to the tutorial in “<strong>1. Getting Ready/Lesson 2 Props and Map</strong>”, and connect it to port 8 of CoreX controller.</p></li><li><p>Install WonderCode software referring to the instructions provided in “<strong>3. Scratch Programming/Lesson 1 WonderCode Installation</strong>”.</p></li></ol><h3 id="_4-2-6-program-logic" tabindex="-1">4.2.6 Program Logic <a class="header-anchor" href="#_4-2-6-program-logic" aria-label="Permalink to &quot;4.2.6 Program Logic&quot;">​</a></h3><ol><li>Upon AiArm starts, it will initialize the dot matrix display. Then set the port to connect the module, which should be consistent with the port where the dot matrix display is connected, and the brightness, followed by the displayed content.</li><li>Please execute the following steps to enable the dot matrix display to demonstrate.</li></ol><p>​ (1) Drag the main program of AiArm to the script zone.</p><p>​ (2) Set the port to 8, and brightness to 8.</p><p>​ (3) Set the port to 8, position to 1, and displayed number to 123.</p><p>​ (4) Turn off the dot matrix display in 1 second.</p><h3 id="_4-2-7-connection" tabindex="-1">4.2.7 Connection <a class="header-anchor" href="#_4-2-7-connection" aria-label="Permalink to &quot;4.2.7 Connection&quot;">​</a></h3><ol><li>Connect the CoreX controller and computer using USB cable, then turn on the controller.</li></ol><img loading="lazy" height="427" width="918" src="'+V+'" class="common_img" style="width:800px;"><ol start="2"><li>Open “<strong>WonderCode</strong>” software.</li></ol><img loading="lazy" height="101" width="72" src="'+O+'" class="common_img" style="width:300px;"><ol start="3"><li>Click on the <img loading="lazy" height="65" width="75" src="'+o+'" class="inline-icon"> located at the lower left corner and select <strong>AiArm</strong> from the available options. This software will automatically establish a connection with AiArm in the subsequent operations.</li></ol><img loading="lazy" height="861" width="1384" src="'+B+'" class="common_img" style="width:800px;"><ol start="4"><li>Click-on <img loading="lazy" height="48" width="154" src="'+W+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p><img loading="lazy" height="108" width="525" src="'+v+'" class="common_img" style="width:800px;"></div><ol start="5"><li>Once the connection is established successfully, the below prompt will appear.</li></ol><img loading="lazy" height="162" width="606" src="'+I+'" class="common_img" style="width:800px;"><h3 id="_4-2-8-write-programs" tabindex="-1">4.2.8 Write Programs <a class="header-anchor" href="#_4-2-8-write-programs" aria-label="Permalink to &quot;4.2.8 Write Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="65" width="75" src="'+o+'" class="inline-icon"> at the lower left corner. Then enter <strong>“Output Module”</strong> section and select dot matrix display.</li></ol><img loading="lazy" height="893" width="1386" src="'+T+'" class="common_img" style="width:800px;"><ol start="2"><li>Set the port in the main program of AiArm to 8, brightness to 8, position to 1 and displayed number to 123.</li></ol><img loading="lazy" height="161" width="542" src="'+S+'" class="common_img" style="width:800px;"><ol start="3"><li>Turn off the dot matrix display in 1 second.</li></ol><img loading="lazy" height="256" width="666" src="'+N+'" class="common_img" style="width:800px;"><h3 id="_4-2-9-download-programs" tabindex="-1">4.2.9 Download Programs <a class="header-anchor" href="#_4-2-9-download-programs" aria-label="Permalink to &quot;4.2.9 Download Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="45" width="46" src="'+P+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="119" width="442" src="'+z+'" class="common_img" style="width:800px;"><ol start="2"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+G+'" class="common_img" style="width:800px;"><h3 id="_4-2-10-save-programs" tabindex="-1">4.2.10 Save Programs <a class="header-anchor" href="#_4-2-10-save-programs" aria-label="Permalink to &quot;4.2.10 Save Programs&quot;">​</a></h3><ol><li>Click-on <strong>File -&gt; Save to your computer.</strong></li></ol><img loading="lazy" height="175" width="513" src="'+Q+'" class="common_img" style="width:800px;"><h3 id="_4-2-11-program-outcome" tabindex="-1">4.2.11 Program Outcome <a class="header-anchor" href="#_4-2-11-program-outcome" aria-label="Permalink to &quot;4.2.11 Program Outcome&quot;">​</a></h3><ol><li>Once the program is downloaded successfully, turn on CoreX controller. Then the dot matrix module will display number <strong>“123”</strong>, and turn off in 1 second.</li></ol><h2 id="_4-3-mp3-module" tabindex="-1">4.3 MP3 Module <a class="header-anchor" href="#_4-3-mp3-module" aria-label="Permalink to &quot;4.3 MP3 Module&quot;">​</a></h2><ol><li>Once the program is downloaded successfully, press button A on CoreX controller to enable the MP3 module to play music.</li><li>If you want to pause the music, press button B.</li></ol><h3 id="_4-3-1-introduction" tabindex="-1">4.3.1 Introduction <a class="header-anchor" href="#_4-3-1-introduction" aria-label="Permalink to &quot;4.3.1 Introduction&quot;">​</a></h3><ol><li>The MP3 module can play the music stored on the inserted TF card.</li><li>Along with its primary function of music playback, it also allows you to switch between songs and adjust the volume to suit your preferences.</li></ol><img loading="lazy" height="284" width="505" src="'+D+'" class="common_img" style="width:400px;"><h3 id="_4-3-2-working-logic" tabindex="-1">4.3.2 Working Logic <a class="header-anchor" href="#_4-3-2-working-logic" aria-label="Permalink to &quot;4.3.2 Working Logic&quot;">​</a></h3><ol><li>The MP3 module incorporates IIC communication and leverages a Digital Signal Processor (DSP) to handle the transmission and decoding of MP3 files. Firstly, the module&#39;s main chip retrieves MP3 files from the storage and reads the signal from the memory to the decoding circuit for decoding.</li><li>Subsequently, the decoded digital signal is converted into an analog signal using a digital-to-analog converter (DAC). The converted analog signal is then amplified and finally outputted to headphones through a Lowpass Filter (LPF), enabling the playback of music.</li></ol><h3 id="_4-3-3-module-features" tabindex="-1">4.3.3 Module Features <a class="header-anchor" href="#_4-3-3-module-features" aria-label="Permalink to &quot;4.3.3 Module Features&quot;">​</a></h3><ol><li><p>Support FAT16 and FAT32 file systems</p></li><li><p>Can play the songs in the format of MP3, WAV and WMA</p></li><li><p>Can hold TF card with a storage of 32GB.</p></li></ol><h3 id="_4-3-4-module-parameters" tabindex="-1">4.3.4 Module Parameters <a class="header-anchor" href="#_4-3-4-module-parameters" aria-label="Permalink to &quot;4.3.4 Module Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Working Voltage</th><th style="text-align:center;">Communication Method</th><th style="text-align:center;">Size</th></tr></thead><tbody><tr><td style="text-align:center;">5V</td><td style="text-align:center;">I2C</td><td style="text-align:center;">48mm*24mm</td></tr></tbody></table><h3 id="_4-3-5-preparation" tabindex="-1">4.3.5 Preparation <a class="header-anchor" href="#_4-3-5-preparation" aria-label="Permalink to &quot;4.3.5 Preparation&quot;">​</a></h3><p>Please follow the below instructions to prepare for writing a program.</p><ol><li>Insert the TF card to any USB port on your computer using a card reader. Then create a new folder named <strong>“MP3”</strong> within the TF card.</li></ol><img loading="lazy" height="413" width="764" src="'+L+'" class="common_img" style="width:400px;"><ol start="2"><li>Move the songs to be played, stored in the <strong>Appendix -&gt; MP3 files</strong>, and drag them into the newly created folder. In addition to the provided songs, you have the option to import other songs into this folder.</li><li>When naming the songs, please use the format: 0011 + song name or 0011, and so on, for each consecutive song. Please be aware that songs 1-10 are preset voice commands and must not be altered, as it may adversely affect the subsequent MP3 broadcast game.</li></ol><img loading="lazy" height="565" width="759" src="'+K+'" class="common_img" style="width:600px;"><ol start="4"><li><p>Please install the MP3 module onto the specific position, and connect it to port 6 of CoreX controller, according to the instructions provided in “<strong>1. Getting Ready/Lesson 2 Props and Map</strong>”.</p></li><li><p>Install WonderCode programming software referring to the file saved in “<strong>3. Scratch Programming/Lesson 1 WonderCode Installation</strong>”.</p></li></ol><h3 id="_4-3-6-program-logic" tabindex="-1">4.3.6 Program Logic <a class="header-anchor" href="#_4-3-6-program-logic" aria-label="Permalink to &quot;4.3.6 Program Logic&quot;">​</a></h3><ol><li>Firstly, the MP3 module will be initialized. Then you can press button A to play music and button B to pause the music. The specific routine is as below.</li></ol><p>​ (1) When AiArm is powered on: initialize the port as 6, and the volume as 15.</p><p>​ (2) When button A is briefly pressed: the number of song to be played: 11</p><p>​ (3) When button B is briefly pressed: MP3 module: stop</p><h3 id="_4-3-7-connection" tabindex="-1">4.3.7 Connection <a class="header-anchor" href="#_4-3-7-connection" aria-label="Permalink to &quot;4.3.7 Connection&quot;">​</a></h3><ol><li>Connect the CoreX controller and computer using USB cable, then turn on the controller.</li></ol><img loading="lazy" height="427" width="918" src="'+R+'" class="common_img" style="width:800px;"><ol start="2"><li>Open “<strong>WonderCode</strong>” software.</li></ol><img loading="lazy" height="101" width="72" src="'+F+'" class="common_img" style="width:300px;"><ol start="3"><li>Click on the <img loading="lazy" height="65" width="75" src="'+a+'" class="inline-icon"> located at the lower left corner and select <strong>AiArm</strong> from the available options. This software will automatically establish a connection with AiArm in the subsequent operations.</li></ol><img loading="lazy" height="861" width="1384" src="'+H+'" class="common_img" style="width:800px;"><ol start="4"><li>Click-on <img loading="lazy" height="48" width="154" src="'+X+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p><img loading="lazy" height="108" width="525" src="'+Y+'" class="common_img" style="width:800px;"></div><ol start="5"><li>Once the connection is established successfully, the below prompt will appear.</li></ol><img loading="lazy" height="162" width="606" src="'+U+'" class="common_img" style="width:800px;"><h3 id="_4-3-8-write-programs" tabindex="-1">4.3.8 Write Programs <a class="header-anchor" href="#_4-3-8-write-programs" aria-label="Permalink to &quot;4.3.8 Write Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="65" width="75" src="'+a+'" class="inline-icon"> at the lower left corner. Then enter <strong>“Output Module”</strong> section and select MP3 module.</li></ol><img loading="lazy" height="451" width="1294" src="'+E+'" class="common_img" style="width:800px;"><ol start="2"><li>Initialize the port connecting to MP3 module as 6, and set the volume as 15.</li></ol><img loading="lazy" height="156" width="307" src="'+J+'" class="common_img" style="width:500px;"><ol start="3"><li>Then control the playback and pause of the music through the two events: <strong>when button A is briefly pressed</strong> and <strong>when the B key is briefly pressed</strong>.</li></ol><img loading="lazy" height="170" width="620" src="'+Z+'" class="common_img" style="width:800px;"><ol start="4"><li>The complete code block is as below.</li></ol><img loading="lazy" height="340" width="702" src="'+j+'" class="common_img" style="width:800px;"><h3 id="_4-3-9-download-programs" tabindex="-1">4.3.9 Download Programs <a class="header-anchor" href="#_4-3-9-download-programs" aria-label="Permalink to &quot;4.3.9 Download Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="45" width="46" src="'+_+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="119" width="442" src="'+$+'" class="common_img" style="width:800px;"><ol start="2"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+tt+'" class="common_img" style="width:800px;"><h3 id="_4-3-10-save-programs" tabindex="-1">4.3.10 Save Programs <a class="header-anchor" href="#_4-3-10-save-programs" aria-label="Permalink to &quot;4.3.10 Save Programs&quot;">​</a></h3><ol><li>Click-on <strong>File -&gt; Save to your computer.</strong></li></ol><img loading="lazy" height="175" width="513" src="'+et+'" class="common_img" style="width:800px;"><h3 id="_4-3-11-program-outcome" tabindex="-1">4.3.11 Program Outcome <a class="header-anchor" href="#_4-3-11-program-outcome" aria-label="Permalink to &quot;4.3.11 Program Outcome&quot;">​</a></h3><ol><li>Once the program is downloaded successfully, power on AiArm.</li><li>Then press button A to play music. If you want to pause the music, press button B.</li></ol><h2 id="_4-4-ultrasonic-ranging-and-display" tabindex="-1">4.4 Ultrasonic Ranging and Display <a class="header-anchor" href="#_4-4-ultrasonic-ranging-and-display" aria-label="Permalink to &quot;4.4 Ultrasonic Ranging and Display&quot;">​</a></h2><ol><li>Once the program is downloaded successfully, the dot matrix display will display the distance measured by ultrasonic sensor.</li></ol><h3 id="_4-4-1-module-introduction" tabindex="-1">4.4.1 Module Introduction <a class="header-anchor" href="#_4-4-1-module-introduction" aria-label="Permalink to &quot;4.4.1 Module Introduction&quot;">​</a></h3><ol><li>This module is an advanced ultrasonic ranging device that emits and receives ultrasonic waves using a industrial-grade ultrasonic ranging chip. The chip incorporates essential components like the ultrasonic transmitting circuit, ultrasonic receiving circuit, and digital processing circuit.</li><li>The module has an IIC communication interface, enabling the retrieval of distance measured by the ultrasonic sensor via IIC communication.</li></ol><img loading="lazy" height="339" width="289" src="'+ot+'" class="common_img" style="width:400px;"><h3 id="_4-4-2-working-logic" tabindex="-1">4.4.2 Working Logic <a class="header-anchor" href="#_4-4-2-working-logic" aria-label="Permalink to &quot;4.4.2 Working Logic&quot;">​</a></h3><ol><li><p>The distance measurement principle of this module is based on an automated process. It initiates by transmitting 8 square waves at a frequency of 40kHz and subsequently detects the presence of a signal return. When a signal return is detected, the module generates a high-level output, and the duration of this high-level signal corresponds to the time taken by the ultrasonic wave to travel from transmission to return.</p></li><li><p>To calculate the measured distance, the following formula is utilized: <strong>test distance = (high-level time * speed of sound (340m/s))/2.</strong></p></li></ol><h3 id="_4-4-3-module-features" tabindex="-1">4.4.3 Module Features <a class="header-anchor" href="#_4-4-3-module-features" aria-label="Permalink to &quot;4.4.3 Module Features&quot;">​</a></h3><ol><li>The ultrasonic probe of this module is equipped with 2 RGB lights. These lights’s brightness can be adjusted, and color can be changed by manipulating the changes in the red (R), green (G), and blue (B) color channels, as well as their combinations.</li><li>This versatile module finds extensive applications, particularly in implementing obstacle avoidance functionality for intelligent vehicles and robots.</li></ol><h3 id="_4-4-4-module-parameters" tabindex="-1">4.4.4 Module Parameters <a class="header-anchor" href="#_4-4-4-module-parameters" aria-label="Permalink to &quot;4.4.4 Module Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Working voltage</th><th style="text-align:center;">Communication</th><th style="text-align:center;">Working current</th><th style="text-align:center;">Size</th></tr></thead><tbody><tr><td style="text-align:center;">5V</td><td style="text-align:center;">I2C</td><td style="text-align:center;">2mA</td><td style="text-align:center;">46mm*20mm</td></tr></tbody></table><h3 id="_4-4-5-preparation" tabindex="-1">4.4.5 Preparation <a class="header-anchor" href="#_4-4-5-preparation" aria-label="Permalink to &quot;4.4.5 Preparation&quot;">​</a></h3><ol><li>Please follow the below instructions to prepare for writing a program.</li></ol><p>​ (1) Please install the ultrasonic sensor and dot matrix display onto the specific position , according to the instructions provided in “<strong>1. Getting Ready/Lesson 2 Props and Map</strong>”. Connect ultrasonic sensor to port 4 of CoreX controller, and dot matrix display to port 8</p><p>​ (2) Install WonderCode programming software referring to the file saved in “<strong>3. Scratch Programming/Lesson 1 WonderCode Installation</strong>”.</p><h3 id="_4-4-6-program-logic" tabindex="-1">4.4.6 Program Logic <a class="header-anchor" href="#_4-4-6-program-logic" aria-label="Permalink to &quot;4.4.6 Program Logic&quot;">​</a></h3><ol><li>Upon program initialization, the dot matrix display will be initialized and the appropriate parameters will be set such as the number of ports connecting the display and the desired brightness level.</li><li>Subsequently, a repetitive loop instruction is employed to continuously retrieve distance measurements from the ultrasonic sensor. These measurements are then displayed on the dot matrix display.</li></ol><h3 id="_4-4-7-connection" tabindex="-1">4.4.7 Connection <a class="header-anchor" href="#_4-4-7-connection" aria-label="Permalink to &quot;4.4.7 Connection&quot;">​</a></h3><ol><li>Connect the CoreX controller and computer using USB cable, then turn on the controller.</li></ol><img loading="lazy" height="427" width="918" src="'+at+'" class="common_img" style="width:800px;"><ol start="2"><li>Open “<strong>WonderCode</strong>” software.</li></ol><img loading="lazy" height="101" width="72" src="'+it+'" class="common_img" style="width:300px;"><ol start="3"><li>Click on the <img loading="lazy" height="65" width="75" src="'+i+'" class="inline-icon"> located at the lower left corner and select <strong>AiArm</strong> from the available options.</li></ol><img loading="lazy" height="861" width="1384" src="'+st+'" class="common_img" style="width:800px;"><ol start="4"><li>Click-on <img loading="lazy" height="48" width="154" src="'+nt+'" class="inline-icon"> and select the corresponding COM port, for example COM4. Please note that COM port options may differ from each computer.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>please do not select COM1, as it used for communication port in general.</strong></p><img loading="lazy" height="108" width="525" src="'+lt+'" class="common_img" style="width:800px;"></div><ol start="5"><li>Once the connection is established successfully, the below prompt will appear.</li></ol><img loading="lazy" height="162" width="606" src="'+rt+'" class="common_img" style="width:800px;"><h3 id="_4-4-8-write-programs" tabindex="-1">4.4.8 Write Programs <a class="header-anchor" href="#_4-4-8-write-programs" aria-label="Permalink to &quot;4.4.8 Write Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="65" width="75" src="'+i+'" class="inline-icon"> at the lower left corner. Then enter <strong>“Output Module”</strong> section to select Dot matrix display, then ultrasonic sensor in sensor section.</li></ol><img loading="lazy" height="671" width="1267" src="'+ct+'" class="common_img" style="width:800px;"><ol start="2"><li>Add the following block, and set the brightness as 8.</li></ol><img loading="lazy" height="128" width="953" src="'+dt+'" class="common_img" style="width:800px;"><ol start="3"><li>Add repetitive loop instruction. It includes the addition of the dot matrix display interface at position 1 to display the number representing the obstacle distance detected by the ultrasonic interface at position 4.</li></ol><img loading="lazy" height="154" width="1069" src="'+gt+'" class="common_img" style="width:800px;"><ol start="4"><li>The complete code block is as below.</li></ol><img loading="lazy" height="225" width="1077" src="'+mt+'" class="common_img" style="width:800px;"><h3 id="_4-4-9-download-programs" tabindex="-1">4.4.9 Download Programs <a class="header-anchor" href="#_4-4-9-download-programs" aria-label="Permalink to &quot;4.4.9 Download Programs&quot;">​</a></h3><ol><li>Click-on <img loading="lazy" height="45" width="46" src="'+ht+'" class="inline-icon"> icon to upload the complete program.</li></ol><img loading="lazy" height="119" width="442" src="'+At+'" class="common_img" style="width:800px;"><ol start="2"><li>The upload may take some times, and please be patient!</li></ol><img loading="lazy" height="34" width="121" src="'+pt+'" class="common_img" style="width:300px;"><h3 id="_4-4-10-save-programs" tabindex="-1">4.4.10 Save Programs <a class="header-anchor" href="#_4-4-10-save-programs" aria-label="Permalink to &quot;4.4.10 Save Programs&quot;">​</a></h3><ol><li>Click-on <strong>File -&gt; Save to your computer.</strong></li></ol><img loading="lazy" height="175" width="513" src="'+ut+'" class="common_img" style="width:800px;"><h3 id="_4-4-11-program-outcome" tabindex="-1">4.4.11 Program Outcome <a class="header-anchor" href="#_4-4-11-program-outcome" aria-label="Permalink to &quot;4.4.11 Program Outcome&quot;">​</a></h3><ol><li>Once the program is downloaded successfully, power on AiArm.</li><li>Dot matrix display will demonstrate the distance from the obstacle measured by ultrasonic sensor</li></ol>',199)])])}const Vt=s(wt,[["render",yt]]);export{qt as __pageData,Vt as default};
